) -> Vec<(std::ops::Range<usize>, HighlightStyle)> {
    let mut highlighter = SyntaxHighlighter::new("json");
    highlighter.update(None, &Rope::from(line), None);
    highlighter.styles(&(0..line.len()), theme)
}

